    Any]], path_params: dict[str, str]) ->tuple[str, dict[str, str]]:
    for key, convertor in param_convertors.items():
        if key in path_params:
            value = path_params[key]
            value = convertor.to_string(value)
            path = path.replace("{%s}" % key, value)
    remaining_params = {k: v for k, v in path_params.items() if k not in param_convertors}
    return path, remaining_params

def __init__(self, host: str, app: ASGIApp, name: (str | None)=None) ->None:
    assert not host.startswith("/"), "Host must not start with '/'"
    self.host = host
    self.app = app
    self.name = name
    self.host_regex, self.host_format, self.param_convertors = compile_path(host)

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    for route in self.routes:
        try:
            return route.url_path_for(name, **path_params)
